<?php
session_start();
require_once dirname(__DIR__, 2) . '/includes/auditoria.php';
orionRegistrarAtividade();
if (!isset($_SESSION['usuario_id'])) { header('Location: ../../index.php'); exit; }
date_default_timezone_set('America/Sao_Paulo');
$base = dirname(__DIR__, 2);
require __DIR__ . '/servico.php';
function h($valor): string { return htmlspecialchars((string)($valor ?? ''), ENT_QUOTES, 'UTF-8'); }
$statusNomes = ['aguardando_envio' => 'Aguardando envio', 'em_manutencao' => 'Em manutenção', 'concluido' => 'Concluído'];
$erro = ''; $pessoas = $ativos = $listas = $solicitacoes = [];
try {
    foreach (['ativos', 'inativos', 'terceiros'] as $grupo) foreach (manutencaoLer($base . '/data/colaboradores/' . $grupo . '.json') as $pessoa) { $pessoas[(string)$pessoa['id']] = $pessoa; if ($grupo !== 'inativos') $ativos[(string)$pessoa['id']] = $pessoa; }
    $listas = manutencaoInventario($base); $solicitacoes = manutencaoLer($base . '/data/solicitacoes_manutencao/solicitacoes.json');
} catch (Throwable $e) { $erro = 'Não foi possível carregar os dados da pasta /data.'; }
if ($_SERVER['REQUEST_METHOD'] === 'POST' && !$erro) {
    try {
        if (!hash_equals($_SESSION['manutencao_csrf'] ?? '', (string)($_POST['csrf'] ?? '')) || empty($_SESSION['manutencao_csrf'])) throw new RuntimeException('Sessão inválida. Atualize a página.');
        $_SESSION['manutencao_mensagem'] = manutencaoExecutar($base, $_POST, $ativos);
        header('Location: manutencao.php'); exit;
    } catch (Throwable $e) { $erro = $e instanceof RuntimeException ? $e->getMessage() : 'Não foi possível salvar a solicitação.'; }
}
$_SESSION['manutencao_csrf'] ??= bin2hex(random_bytes(32));
$idPessoa = (string)($_GET['colaborador_id'] ?? ''); $busca = trim((string)($_GET['busca'] ?? '')); $statusFiltro = (string)($_GET['status'] ?? 'ativas');
$itens = []; $porId = [];
foreach ($listas as $fonte => $lista) foreach ($lista as $item) { $item['_chave'] = $fonte . ':' . $item['id']; $itens[] = $item; $porId[(string)$item['id']] = $item; }
$opcoes = array_values(array_filter($itens, fn($item) => ($idPessoa === '' || (string)($item['colaborador_id'] ?? '') === $idPessoa) && ($busca === '' || stripos(($item['patrimonio'] ?? '') . ' ' . ($item['hostname'] ?? '') . ' ' . ($item['marca'] ?? '') . ' ' . ($item['modelo'] ?? ''), $busca) !== false)));
$chave = (string)($_POST['equipamento'] ?? $_GET['equipamento'] ?? ''); $selecionado = null; foreach ($itens as $item) if ($item['_chave'] === $chave) $selecionado = $item;
$exibidas = array_values(array_filter($solicitacoes, function($s) use ($idPessoa, $busca, $statusFiltro, $porId) {
    $equip = $porId[(string)($s['equipamento_relacionado_id'] ?? '')] ?? [];
    $pessoa = (string)($s['colaborador_id'] ?? $equip['colaborador_id'] ?? '');
    return ($idPessoa === '' || $pessoa === $idPessoa) && ($busca === '' || stripos(($s['patrimonio'] ?? '') . ' ' . ($equip['hostname'] ?? '') . ' ' . ($equip['modelo'] ?? ''), $busca) !== false) && ($statusFiltro === 'todas' || ($statusFiltro === 'ativas' ? $s['status'] !== 'concluido' : $s['status'] === $statusFiltro));
}));
usort($exibidas, fn($a,$b) => (int)$b['id'] <=> (int)$a['id']); uasort($pessoas, fn($a,$b) => strcasecmp($a['nome'], $b['nome'])); uasort($ativos, fn($a,$b) => strcasecmp($a['nome'], $b['nome']));
$mensagem = $_SESSION['manutencao_mensagem'] ?? ''; unset($_SESSION['manutencao_mensagem']);
?>
