<form method="get" class="maintenance-load"><input type="hidden" name="colaborador_id" value="<?= h($idPessoa) ?>"><input type="hidden" name="busca" value="<?= h($busca) ?>"><input type="hidden" name="status" value="<?= h($statusFiltro) ?>"><label class="equipment-collaborator-field" data-equipment-combobox>Equipamento<select name="equipamento" class="equipment-type-select" required><option value="">Selecione um equipamento</option><?php foreach ($opcoes as $item): ?><option value="<?= h($item['_chave']) ?>" data-patrimonio="<?= h($item['patrimonio'] ?? '') ?>" <?= $chave === $item['_chave'] ? 'selected' : '' ?>><?= h(($item['marca'] ?? '') . ' ' . ($item['modelo'] ?? '') . ' · Patrimônio ' . ($item['patrimonio'] ?? '—') . ' · ' . ($item['hostname'] ?? ucfirst($item['tipo'] ?? ''))) ?></option><?php endforeach; ?></select></label><button class="equipment-primary" type="submit">Carregar</button></form></section>
<?php if ($selecionado): ?><section class="equipment-form-panel"><div class="maintenance-equipment"><i class="fas fa-<?= in_array($selecionado['tipo'] ?? '', ['notebook','desktop'], true) ? 'laptop' : 'tools' ?>" aria-hidden="true"></i><div><h2><?= h(($selecionado['marca'] ?? '') . ' ' . ($selecionado['modelo'] ?? '')) ?></h2><p>Patrimônio <?= h($selecionado['patrimonio'] ?? '—') ?> · Serial <?= h($selecionado['serial'] ?? '—') ?> · <?= h($selecionado['hostname'] ?? '') ?></p><p>Colaborador: <?= h($pessoas[(string)($selecionado['colaborador_id'] ?? '')]['nome'] ?? 'Sem alocação') ?> · Status: <?= h(str_replace('_',' ', $selecionado['status'] ?? '')) ?></p></div></div>
<?php if (!in_array($selecionado['status'] ?? '', ['manutencao','fora_uso','pendente_devolucao'], true)): ?><form method="post" class="equipment-form" data-maintenance-open><input type="hidden" name="csrf" value="<?= h($_SESSION['manutencao_csrf']) ?>"><input type="hidden" name="acao" value="abrir"><input type="hidden" name="equipamento" value="<?= h($chave) ?>"><label>Modalidade<select name="modalidade" class="equipment-type-select" required><option value="interna" <?= ($_POST['modalidade'] ?? '') === 'interna' ? 'selected' : '' ?>>Manutenção interna</option><option value="externa" <?= ($_POST['modalidade'] ?? '') === 'externa' ? 'selected' : '' ?>>Manutenção externa</option></select></label><label data-maintenance-vendor>Prestador / responsável externo<input name="destino_reparo" maxlength="255" value="<?= h($_POST['destino_reparo'] ?? '') ?>" placeholder="Nome do técnico ou assistência"></label><label>Prioridade<select name="prioridade"><option value="normal">Normal</option><option value="baixa">Baixa</option><option value="alta">Alta</option><option value="urgente">Urgente</option></select></label><label class="equipment-form-wide">Descrição do problema<textarea name="descricao_problema" rows="4" maxlength="5000" required><?= h($_POST['descricao_problema'] ?? '') ?></textarea></label><div class="equipment-form-wide maintenance-actions"><button class="equipment-primary" type="submit">Abrir manutenção</button><span>A externa começa aguardando envio; a interna começa em manutenção.</span></div></form><?php else: ?><p>Este equipamento não pode iniciar uma nova manutenção no status atual.</p><?php endif; ?></section><?php endif; ?>
<section class="equipment-list"><div class="equipment-list-heading"><h2>Solicitações de manutenção</h2><span><?= count($exibidas) ?> solicitações</span></div><?php if (!$exibidas): ?><div class="equipment-empty"><i class="fas fa-tools" aria-hidden="true"></i><p>Nenhuma solicitação encontrada.</p></div><?php endif; ?>
<?php foreach ($exibidas as $s): $equip = $porId[(string)($s['equipamento_relacionado_id'] ?? '')] ?? []; $modalidade = $s['modalidade'] ?? 'externa'; ?><article class="maintenance-card"><div class="maintenance-card-heading"><div class="maintenance-icon"><i class="fas fa-tools" aria-hidden="true"></i><strong>#<?= h($s['id']) ?></strong></div><div><strong><?= h(($equip['marca'] ?? '') . ' ' . ($equip['modelo'] ?? ucfirst($s['tipo_equipamento'] ?? 'Equipamento'))) ?></strong><small>Patrimônio <?= h($s['patrimonio'] ?? '—') ?> · <?= $modalidade === 'interna' ? 'Interna' : 'Externa' ?> · <?= h($s['destino_reparo'] ?? '—') ?></small><small><?= h($s['colaborador_nome'] ?? $pessoas[(string)($s['colaborador_id'] ?? $equip['colaborador_id'] ?? '')]['nome'] ?? 'Sem colaborador') ?></small></div><span class="maintenance-status maintenance-status-<?= h(isset($statusNomes[$s['status']]) ? $s['status'] : 'outro') ?>"><?= h($statusNomes[$s['status']] ?? $s['status']) ?></span><time><?= h(date('d/m/Y', strtotime($s['data_envio']))) ?></time></div><details <?= ($_POST['id'] ?? '') === (string)$s['id'] ? 'open' : '' ?>><summary>Detalhes / ações</summary><p class="maintenance-description"><?= h($s['descricao_problema']) ?></p><p>Prioridade: <?= h(ucfirst($s['prioridade'] ?? 'normal')) ?> · Responsável: <?= h($s['responsavel_envio'] ?? '—') ?></p>
<?php if ($s['status'] === 'aguardando_envio'): ?><form method="post" class="maintenance-start"><input type="hidden" name="csrf" value="<?= h($_SESSION['manutencao_csrf']) ?>"><input type="hidden" name="acao" value="iniciar"><input type="hidden" name="id" value="<?= h($s['id']) ?>"><button class="equipment-primary" type="submit">Confirmar envio / iniciar reparo</button></form><?php endif; ?>
<?php if ($s['status'] !== 'concluido'): ?><form method="post" class="equipment-form maintenance-finish" data-maintenance-finish data-confirm="Concluir a manutenção e mover o equipamento para o destino selecionado?"><input type="hidden" name="csrf" value="<?= h($_SESSION['manutencao_csrf']) ?>"><input type="hidden" name="acao" value="concluir"><input type="hidden" name="id" value="<?= h($s['id']) ?>"><label>Destino após o reparo<select name="destino_conclusao" class="equipment-type-select" required><option value="estoque">Inventário</option><option value="interno">Uso interno</option><option value="fora_uso">Fora de uso</option><option value="alocado">Alocar a colaborador</option></select></label><label class="equipment-collaborator-field" data-collaborator-combobox data-maintenance-collaborator>Colaborador<select name="colaborador_id"><option value="">Selecione um colaborador</option><?php foreach ($ativos as $pessoa): ?><option value="<?= h($pessoa['id']) ?>"><?= h($pessoa['nome'] . ' · ' . ($pessoa['departamento'] ?? '')) ?></option><?php endforeach; ?></select></label><label class="equipment-form-wide">Resultado do reparo<textarea name="solucao" rows="3" maxlength="5000" required><?= ($_POST['id'] ?? '') === (string)$s['id'] ? h($_POST['solucao'] ?? '') : '' ?></textarea></label><div class="equipment-form-wide"><button class="equipment-primary" type="submit">Concluir manutenção</button></div></form><?php else: ?><p class="maintenance-description"><strong>Resultado:</strong> <?= h($s['solucao'] ?? 'Conclusão registrada no banco anterior.') ?></p><p>Destino: <?= h($s['destino_conclusao'] ?? '—') ?> · Concluído em <?= h(date('d/m/Y H:i', strtotime($s['data_conclusao']))) ?></p><?php endif; ?><details class="maintenance-history"><summary>Histórico de status</summary><?php foreach (($s['historico_status'] ?? []) as $historico): ?><p><?= h(date('d/m/Y H:i', strtotime($historico['data']))) ?> · <?= h($statusNomes[$historico['status']] ?? $historico['status']) ?> · <?= h($historico['usuario'] ?? '—') ?></p><?php endforeach; ?></details></details></article><?php endforeach; ?></section></main><footer><p>Orion Inventory © 2023 - 2026 - Todos os direitos reservados</p></footer></body></html>
